it('reports an orphaned Runtime check instead of claiming the change is healthy', async () => {
    const name = 'orphaned-check-doctor';
    await fs.mkdir(path.join(projectRoot, '.git'));
    await refreshRuntimePaths();
    await createPortable(name);
    await fs.writeFile(
      path.join(nativePortableChangeDir(paths, name), 'brief.md'),
      '# Acceptance examples\n- Doctor reports an orphaned check owner.\n',
    );
    await confirmNativePortableShape({ paths, name });
    const runner = createNativeRunnerChannel();
    const state = await submitNativePortableBuilderCandidate({
      paths,
      name,
      input: {
        identity: runner.captureExecutionIdentity({
          identityProvider: 'test-host',
          executionRef: 'orphaned-doctor-builder',
        }),
        candidateId: 'orphaned-doctor-candidate',
        summary: 'Implemented.',
        addressedAcceptanceIds: ['A1'],
        acceptanceReview: fixtureAcceptanceReview(['A1']),
        review: null,
      },
    });
    const marker = path.join(projectRoot, 'orphaned-doctor-starts.txt');
    const plan = {
      id: 'orphaned-doctor-check',
      name: 'Orphaned Doctor check',
      executable: process.execPath,
      argv: [
        '-e',
        "const fs=require('node:fs');fs.writeFileSync(process.argv[1]+'.pid',String(process.pid));fs.appendFileSync(process.argv[1],'start\\n');setInterval(()=>{},1000)",
        marker,
      ],
      cwdRef: '.',
      timeoutMs: 60_000,
      repeatable: true,
    } as const;
    const repositoryRoot = path.resolve(import.meta.dirname, '../../..');
    const file = nativeLocalExecutionFile(paths, name);
    const owner = spawnDoctorCheckProcess({
      repositoryRoot,
      payload: { action: 'execute-checks', paths, name: state.name, plans: [plan] },
    });
    await waitForCondition(async () => {
      const local = await readNativeLocalExecution(file);
      const reserved =
        local?.execution?.status === 'running' &&
        local.checks[0]?.activeProcess?.status === 'running' &&
        typeof local.checks[0].activeProcess.instanceId === 'string';
      const mutationLockReleased = await fs
        .access(path.join(paths.locksDir, 'root-move.lock'))
        .then(() => false)
        .catch(() => true);
      return (
        reserved &&
        mutationLockReleased &&
        (await fs.access(marker).then(
          () => true,
          () => false,
        ))
      );
    }, 'Runtime owner did not start the orphaned Doctor check');
    const running = await readNativeLocalExecution(file);
    const activePid = Number(await fs.readFile(marker + '.pid', 'utf8'));
    expect(activePid).toEqual(expect.any(Number));
    owner.kill('SIGKILL');
    await waitForProcessExit(owner);
    try {
      if (processIsAlive(activePid)) {
        if (process.platform === 'win32')
          (await import('node:child_process')).execFileSync(
            'taskkill',
            ['/PID', String(activePid), '/T', '/F'],
            { stdio: 'ignore' },
          );
        else process.kill(activePid, 'SIGKILL');
      }
    } catch (error) {
      if (processIsAlive(activePid)) throw error;
    }
    await waitForCondition(() => {
      try {
        process.kill(activePid, 0);
        return false;
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code !== 'ESRCH') throw error;
        return true;
      }
    }, 'Doctor check process tree did not stop after its Runtime owner exited');

    await expect(nativeDoctorCommand([name], projectRoot)).resolves.toMatchObject({
      exitCode: 65,
      data: {
        healthy: false,
        findings: [
          expect.objectContaining({
            code: 'portable-check-execution-stuck',
          }),
        ],
      },
    });
    await expect(nativeDoctorCommand([name, '--repair'], projectRoot)).resolves.toMatchObject({
      exitCode: 65,
      data: {
        healthy: false,
        repaired: false,
        result: { reason: 'execution-active' },
      },
    });
    expect(await readNativeLocalExecution(file)).toEqual(running);
    expect(await fs.readFile(marker, 'utf8')).toBe('start\n');
  })

it.each([false, true])(
    'preserves a migrated live Runtime check during Doctor repair (legacy projection: %s)',
    async (legacyProjection) => {
      const name = 'live-check-doctor';
      await fs.mkdir(path.join(projectRoot, '.git'));
      await refreshRuntimePaths();
      await createPortable(name);
      const localRuntime = path.dirname(nativeLocalExecutionFile(paths, name));
      const legacyRuntime = path.join(nativePortableChangeDir(paths, name), 'runtime');
      await fs.cp(localRuntime, legacyRuntime, { recursive: true });
      await fs.rm(localRuntime, { recursive: true });
      paths = await nativeProjectPaths(projectRoot, 'docs');
      const fenceBefore = await fs.readFile(legacyRuntime);
      const evidenceFile = path.join(localRuntime, 'retained-check.log');
      const trajectoryFile = path.join(localRuntime, 'trajectory.jsonl');
      await fs.writeFile(evidenceFile, 'retained check evidence\n');
      await fs.writeFile(trajectoryFile, '{"type":"retained-trajectory"}\n');
      await fs.writeFile(
        path.join(nativePortableChangeDir(paths, name), 'brief.md'),
        '# Acceptance examples\n- Doctor preserves a live Runtime check.\n',
      );
      await confirmNativePortableShape({ paths, name });
      const runner = createNativeRunnerChannel();
      const state = await submitNativePortableBuilderCandidate({
        paths,
        name,
        input: {
          identity: runner.captureExecutionIdentity({
            identityProvider: 'test-host',
            executionRef: 'live-doctor-builder',
          }),
          candidateId: 'live-doctor-candidate',
          summary: 'Implemented.',
          addressedAcceptanceIds: ['A1'],
          acceptanceReview: fixtureAcceptanceReview(['A1']),
          review: null,
        },
      });
      const marker = path.join(projectRoot, 'doctor-check-starts.txt');
      const release = path.join(projectRoot, 'release-doctor-check');
      const plan = {
        id: 'live-doctor-check',
        name: 'Live Doctor check',
        executable: process.execPath,
        argv: [
          '-e',
          "const fs=require('node:fs');fs.appendFileSync(process.argv[1],'start\\n');setInterval(()=>{if(fs.existsSync(process.argv[2]))process.exit(0)},25)",
          marker,
          release,
        ],
        cwdRef: '.',
        timeoutMs: 60_000,
        repeatable: true,
      } as const;
      const repositoryRoot = path.resolve(import.meta.dirname, '../../..');
      const owner = spawnDoctorCheckProcess({
        repositoryRoot,
        payload: { action: 'execute-checks', paths, name: state.name, plans: [plan] },
      });
      const file = nativeLocalExecutionFile(paths, name);
      await waitForCondition(async () => {
        const local = await readNativeLocalExecution(file);
        const reserved =
          local?.execution?.status === 'running' &&
          local.checks[0]?.activeProcess?.status === 'running' &&
          typeof local.checks[0].activeProcess.instanceId === 'string';
        const mutationLockReleased = await fs
          .access(path.join(paths.locksDir, 'root-move.lock'))
          .then(() => false)
          .catch(() => true);
        const commandStarted = await fs
          .access(marker)
          .then(() => true)
          .catch(() => false);
        return reserved && mutationLockReleased && commandStarted;
      }, 'Runtime owner did not start the Doctor test check');

      const beforeRepair = await fs.readFile(file);
      if (legacyProjection) {
        await fs.writeFile(
          path.join(nativePortableChangeDir(paths, name), 'checkpoint.md'),
          'old projection',
        );
      }
      const repaired = await nativeDoctorCommand([name, '--repair'], projectRoot);
      expect(await fs.readFile(file)).toEqual(beforeRepair);
      expect(await fs.readFile(legacyRuntime)).toEqual(fenceBefore);
      expect(await fs.readFile(evidenceFile, 'utf8')).toBe('retained check evidence\n');
      expect(await fs.readFile(trajectoryFile, 'utf8')).toBe('{"type":"retained-trajectory"}\n');
      const duringRepair = await readNativeLocalExecution(file);
      const startsDuringRepair = (await fs.readFile(marker, 'utf8')).trim().split(/\r?\n/);

      await fs.writeFile(release, 'release\n');
      await waitForProcessExit(owner);

      expect(repaired, JSON.stringify(repaired)).toMatchObject({
        exitCode: legacyProjection ? 0 : 65,
        data: {
          healthy: legacyProjection,
          repaired: legacyProjection,
          ...(legacyProjection
            ? { migration: { recovered: true } }
            : { result: { reason: 'execution-active' } }),
        },
      });
      expect(duringRepair).toMatchObject({
        execution: { status: 'running' },
        checks: [{ status: 'running' }],
      });
      expect(startsDuringRepair).toHaveLength(1);
      expect(owner.exitCode).toBe(0);
      await expect(readNativeLocalExecution(file)).resolves.toMatchObject({
        execution: { status: 'completed' },
        checks: [{ status: 'passed' }],
      });
    },
  )

it('takes over a verifier dispatch that never confirmed startup', async () => {
    const name = 'stale-verifier-dispatch';
    await createPortable(name);
    await fs.writeFile(
      path.join(nativePortableChangeDir(paths, name), 'brief.md'),
      '# Acceptance examples\n- The verifier can recover after a lost startup.\n',
    );
    await confirmNativePortableShape({ paths, name });
    const runner = createNativeRunnerChannel();
    await submitNativePortableBuilderCandidate({
      paths,
      name,
      input: {
        identity: runner.captureExecutionIdentity({
          identityProvider: 'test-host',
          executionRef: 'stale-verifier-builder',
        }),
        candidateId: 'stale-verifier-candidate',
        summary: 'Implemented.',
        addressedAcceptanceIds: ['A1'],
        acceptanceReview: fixtureAcceptanceReview(['A1']),
        review: null,
      },
    });
    const executed = await executeNativePortableCheckPlan({ paths, name, plans: [] });
    const dispatched = await dispatchNativePortableVerifier({
      paths,
      name,
      checks: executed.checks,
      verifierExecutionId: 'stale-verifier-execution',
    });
    const local = await readNativeLocalExecution(nativeLocalExecutionFile(paths, name));
    await writeNativeLocalExecution(
      nativeLocalExecutionFile(paths, name),
      {
        ...local!,
        basedOnStateVersion: dispatched.state_version,
        execution: {
          operationId: 'stale-verifier-operation',
          stage: 'verifying',
          actor: 'verifier',
          executionId: 'stale-verifier-execution',
          status: 'running',
          startedAt: new Date(Date.now() - 31 * 60 * 1_000).toISOString(),
          requestCheckRounds: 0,
        },
      },
      { containedRoot: paths.runtimeDir },
    );

    await expect(nativeDoctorCommand([name, '--repair'], projectRoot)).resolves.toMatchObject({
      exitCode: 0,
      data: {
        healthy: true,
        repaired: true,
        result: { verifierTakeover: true, waitedMinutes: expect.any(Number) },
      },
    });
    const recovered = await readNativeLocalExecution(nativeLocalExecutionFile(paths, name));
    expect(recovered?.execution?.status).toBe('running');
    expect(recovered?.execution?.verifierStartedAt).toBeUndefined();
  })

it('repairs an exact empty v2 overlay left beside a legacy v1 child contract', async () => {
    const name = 'stale-v1-overlay';
    const { buildState, file } = await createLegacySupervisorFixture(name);

    await expect(nativeDoctorCommand([name], projectRoot)).resolves.toMatchObject({
      exitCode: 65,
      data: {
        healthy: false,
        findings: [
          expect.objectContaining({
            code: 'portable-supervisor-overlay-stale',
            repairCommand: `comet native doctor ${name} --repair`,
          }),
        ],
      },
    });

    await expect(nativeDoctorCommand([name, '--repair'], projectRoot)).resolves.toMatchObject({
      exitCode: 0,
      data: { healthy: true, repaired: true },
    });
    await expect(fs.stat(file)).rejects.toMatchObject({ code: 'ENOENT' });
    await expect(readNativePortableChange(paths, name)).resolves.toMatchObject({
      name,
      phase: 'build',
      state_version: buildState.state_version,
    });

    await archiveLegacyChild(buildState);

    const applied = await applyNativeRunnerInput({
      paths,
      name,
      input: {
        kind: 'builder-handoff',
        summary: 'The legacy child result is ready for verification.',
        addressed_acceptance_ids: buildState.acceptance.map(({ id }) => id),
        acceptance_review: fixtureAcceptanceReview(buildState.acceptance.map(({ id }) => id)),
        checks: [],
        known_limits: [],
        review: {
          status: 'passed',
          summary: 'Read-only review passed.',
          reviewer_execution_ref: 'reviewer',
        },
      },
      maxVerifyFailures: 3,
    });
    expect(applied.state.phase).toBe('verify');
  })

